    "manual": "Manual",
    "nenhum cortador toca na tesoura ou na enfestadeira se o pedido estiver em quarentena ou sem o sinal de 50%! o sistema bloqueia a alteração de etapa no kanban. o dono só libera quando confirma o pix na conta.": "Nenhum cortador toca na tesoura ou na enfestadeira se o pedido estiver em Quality Hold ou sem o sinal de 50%! O sistema bloqueia a alteração de etapa no Kanban. O dono só libera quando confirma o PIX na conta.",
