    "! seu pagamento foi confirmado com sucesso. configure os dados da sua empresa e defina sua": "! Seu pagamento foi confirmado com Erfolg. Configure os dados da sua empresa e defina sua",
    "! você entrou com a senha temporária definida pela diretoria. por segurança, crie agora sua": "! Você entrou com a senha temporária definida pela diretoria. Por segurança, crie agora sua",
    "elas não precisam mexer! o encarregado imprime a ficha técnica a4 com 1 clique. na folha já vem tudo mastigado: tamanho, modelo, foto da polo e onde assinar. o sistema foi desenhado exatamente para quem vive no chão de fábrica.": "Elas não precisam mexer! O encarregado imprime a Technisches Datenblatt A4 com 1 clique. Na folha já vem tudo mastigado: tamanho, modelo, foto da polo e onde assinar. O sistema foi desenhado exatamente para quem vive no chão de fábrica.",
    "manual": "Manual",
    "nenhum cortador toca na tesoura ou na enfestadeira se o pedido estiver em quarentena ou sem o sinal de 50%! o sistema bloqueia a alteração de etapa no kanban. o dono só libera quando confirma o pix na conta.": "Nenhum cortador toca na tesoura ou na enfestadeira se o pedido estiver em Qualitätssperre ou sem o sinal de 50%! O sistema bloqueia a alteração de etapa no Kanban. O dono só libera quando confirma o PIX na conta.",
    "no fim do mês, você sabe sua margem média líquida por polo e por camiseta, suas despesas fixas de galpão e quanto sobrou limpo. quanto custa você não ter esse controle hoje?": "No fim do mês, você sabe sua margem média líquida por polo e por camiseta, suas despesas fixas de galpão e quanto sobrou limpo. Quanto custa você não ter esse controle hoje?",
